sys_ws_operation.operation_script:
(function process(request, response) {
    if (!(gs.hasRole('x_espaco.leitura') || gs.hasRole('x_espaco.recepcionista') ||
          gs.hasRole('x_espaco.profissional') || gs.hasRole('x_espaco.gestor') || gs.hasRole('x_espaco.admin'))) {
        response.setStatus(403);
        return { error: { code: 403, message: 'Sem permissão para consultar este recurso.' } };
    }
    var gr = new GlideRecord('x_espaco_servico');
    gr.orderBy('nome');
    gr.query();

    var data = [];
    while (gr.next()) {
        data.push({
            sys_id: gr.getUniqueValue(),
            nome: gr.getValue('nome'),
            area_corporal: gr.getValue('area_corporal'),
            duracao_minutos: gr.getValue('duracao_minutos'),
            preco: gr.getValue('preco')
        });
    }

    response.setStatus(200);
    return { data: data, meta: { page: 1, limit: data.length, total: data.length } };
})(request, response);
